namespace {
using V=arkjson::Value;
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
V json(const std::string& source){V value;check(arkjson::parse(source,value),"Bad test JSON");return value;}
template<class F>void rejects(F action,const char* message){bool rejected=false;try{action();}catch(const std::exception&){rejected=true;}check(rejected,message);}
V accepted(const V& reply){if(reply.find("isError")&&reply.find("isError")->b)throw std::runtime_error(reply.find("structuredContent")->dump());check(reply.find("structuredContent"),"Missing receipt");return *reply.find("structuredContent");}
V apply(ark::AgentSession& session,V command){V batch=V::makeObj(),commands=V::makeArr();commands.arr.push_back(std::move(command));batch.set("commands",commands);batch.set("expected_revision",V::makeNum(session.revision));return accepted(session.call("doc_apply",batch));}
V fixture(){ark::Image pixels;pixels.w=4;pixels.h=3;pixels.px.resize(4*3*3);for(size_t i=0;i<pixels.px.size();++i)pixels.px[i]=(unsigned char)(i*7);const auto attachment=ark::assistantImageAttachment(ark::encodePNG(pixels),"stamp.png",ark::AssistantImageDecoder::Portable);V out=V::makeObj();out.set("name",V::makeStr("Logo"));out.set("mime_type",V::makeStr(attachment.mimeType));out.set("data_base64",V::makeStr(attachment.base64));return out;}
V importCommand(){V command=V::makeObj();command.set("op",V::makeStr("image_asset.set"));command.set("asset",fixture());return command;}
V randomAsset(const std::string& name,unsigned seed,int side=64){ark::Image pixels;pixels.w=side;pixels.h=side;pixels.px.resize((size_t)side*side*3);for(auto& channel:pixels.px){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;channel=(unsigned char)seed;}const auto image=ark::assistantImageAttachment(ark::encodePNG(pixels),"synthetic-history.png",ark::AssistantImageDecoder::Portable);V asset=V::makeObj();asset.set("name",V::makeStr(name));asset.set("mime_type",V::makeStr(image.mimeType));asset.set("data_base64",V::makeStr(image.base64));return asset;}
V assetCommand(V asset){V command=V::makeObj();command.set("op",V::makeStr("image_asset.set"));command.set("asset",std::move(asset));return command;}
void historyImages(){ark::AgentSession session;apply(session,json(R"({"op":"param.set","name":"history_baseline","expr":"1"})"));const auto image=randomAsset("Journal image",31);check(image.find("data_base64")->str.size()>1024,"History fixture must exercise packed source blobs");apply(session,assetCommand(image));const auto saved=ark::documentToJson(session.document);ark::Document loaded;std::string error;check(ark::documentFromJson(saved,loaded,&error)&&loaded.imageAssets.size()==1,"New large embedded source is journaled before persisted packing");accepted(session.call("doc_undo",V::makeObj()));check(session.document.imageAssets.empty(),"Image-only Undo restores source vector");accepted(session.call("doc_redo",V::makeObj()));check(session.document.imageAssets.size()==1,"Image-only Redo restores source vector and original bytes");
    V preview=V::makeObj(),commands=V::makeArr();commands.arr.push_back(assetCommand(randomAsset("Prepared image",41)));preview.set("commands",commands);preview.set("expected_revision",V::makeNum(session.revision));const auto receipt=accepted(session.call("doc_preview",preview));check(receipt.find("valid")->b&&receipt.find("candidate_cached")->b,"Embedded source has a retained metadata preview");accepted(session.call("doc_apply",*receipt.find("apply")));check(session.document.imageAssets.size()==2&&session.document.imageAssets.back().name=="Prepared image","Prepared metadata commit retains its embedded source vector");
    const auto temp=std::filesystem::temp_directory_path()/("ark-stamp-import-"+std::to_string(session.revision)+".png");ark::Image pixels;pixels.w=64;pixels.h=64;pixels.px.resize(64*64*3);unsigned seed=57;for(auto& value:pixels.px){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;value=(unsigned char)seed;}check(ark::writePNG(temp.string().c_str(),pixels),"Synthetic path-import fixture writes");V import=V::makeObj();import.set("action",V::makeStr("import"));import.set("name",V::makeStr("Tool import"));import.set("path",V::makeStr(temp.string()));import.set("expected_revision",V::makeNum(session.revision));accepted(session.call("image_asset",import));std::filesystem::remove(temp);check(session.document.imageAssets.size()==3&&ark::documentFromJson(ark::documentToJson(session.document),loaded,&error),"Standalone image_asset path import joins the same atomic history contract");
}
void historyImageCapacity(){ark::AgentSession session;apply(session,json(R"({"op":"param.set","name":"capacity_baseline","expr":"1"})"));V commands=V::makeArr();commands.arr.push_back(assetCommand(randomAsset("Old A",71,512)));commands.arr.push_back(assetCommand(randomAsset("Old B",81,512)));V args=V::makeObj();args.set("expected_revision",V::makeNum(session.revision));args.set("commands",commands);accepted(session.call("doc_apply",args));commands=json(R"([{"op":"image_asset.remove","name":"Old A"},{"op":"image_asset.remove","name":"Old B"}])");args.set("expected_revision",V::makeNum(session.revision));args.set("commands",commands);accepted(session.call("doc_apply",args));check(session.document.imageAssets.empty(),"Old asset pixels remain only in retained immutable history");const auto before=ark::documentToJson(session.document);const auto revision=session.revision;commands=V::makeArr();commands.arr.push_back(assetCommand(randomAsset("New A",91,512)));commands.arr.push_back(assetCommand(randomAsset("New B",101,512)));args.set("commands",commands);args.set("expected_revision",V::makeNum(revision));const auto rejected=session.call("doc_apply",args);check(rejected.find("isError")->b&&session.revision==revision&&session.document.imageAssets.empty()&&ark::documentToJson(session.document)==before,"Post-journal total4MiB failure rolls back all embedded images and source history atomically");}
void assets(){const auto source=fixture();const auto asset=ark::imageAssetFromJson(source);const auto rgba=ark::decodeImageAssetRGBA(asset);check(asset.width==4&&asset.height==3&&rgba.size()==48,"Embedded PNG fully decodes original pixels");for(size_t i=0;i<12;++i){for(size_t channel=0;channel<3;++channel)check(rgba[i*4+channel]==(unsigned char)((i*3+channel)*7),"Source RGB pixels survive embedding");check(rgba[i*4+3]==255,"PNG decoded alpha is retained");}
    check(!ark::imageAssetToJson(asset).find("data_base64"),"Normal asset inspection omits pixels");check(ark::imageAssetFromJson(ark::imageAssetToJson(asset,true)).sha256==asset.sha256,"Exact asset source and hash roundtrip");
    auto forged=ark::imageAssetToJson(asset,true);forged.set("sha256",V::makeStr(std::string(64,'0')));rejects([&]{ark::imageAssetFromJson(forged);},"Tampered source hash rejects");forged=ark::imageAssetToJson(asset,true);forged.set("width",V::makeNum(5));rejects([&]{ark::imageAssetFromJson(forged);},"Forged dimensions reject");forged=source;forged.set("mime_type",V::makeStr("image/jpeg"));rejects([&]{ark::imageAssetFromJson(forged);},"MIME mismatch rejects");forged=source;forged.set("data_base64",V::makeStr(source.find("data_base64")->str.substr(0,32)));rejects([&]{ark::imageAssetFromJson(forged);},"Truncated compressed pixels reject");
    const std::string jpeg="";
    V jpegSource=V::makeObj();jpegSource.set("name",V::makeStr("JPEG"));jpegSource.set("mime_type",V::makeStr("image/jpeg"));jpegSource.set("data_base64",V::makeStr(jpeg));const auto jpegAsset=ark::imageAssetFromJson(jpegSource);const auto jpegPixels=ark::decodeImageAssetRGBA(jpegAsset);check(jpegAsset.width==3&&jpegAsset.height==2&&jpegPixels.size()==24,"Portable embedded JPEG full decode");check(std::abs((int)jpegPixels[0]-50)<=5&&std::abs((int)jpegPixels[1]-100)<=5&&std::abs((int)jpegPixels[2]-150)<=5,"JPEG contains actual fixture pixels");
}
void persistence(){ark::AgentSession session;apply(session,importCommand());apply(session,json(R"({"op":"canvas.set","name":"Sketch logo","asset":"Logo","plane":"XY","width":20,"height":15})"));apply(session,json(R"({"op":"stamp.set","name":"Plane stamp","asset":"Logo","plane":"XZ","origin":[2,3,0],"width":20,"height":15,"opacity":0.6})"));
    const auto saved=ark::documentToJson(session.document,true,false);const auto root=json(saved);check(root.find("version")->num==39&&root.find("image_assets")&&root.find("stamps")&&root.find("canvases")->arr.front().find("asset"),"Embedded plane source recipes select format39");ark::Document restored;std::string error;check(ark::documentFromJson(saved,restored,&error),"Stamp source loads");check(ark::documentToJson(restored,true,false)==saved,"Embedded assets, canvas and stamp roundtrip deterministically");check(restored.authoringCopy().imageAssets.size()==1&&restored.authoringCopy().stamps.size()==1,"Authoring copy retains source images and stamps");
    const auto info=accepted(session.call("doc_info",json(R"({"detail":"design"})")));check(info.find("image_assets")&&!info.find("image_assets")->arr.front().find("data_base64"),"Normal doc_info supplies metadata without large pixel payload");
    const auto before=ark::documentToJson(session.document);const auto revision=session.revision;V bad=json(R"({"expected_revision":0,"commands":[{"op":"stamp.remove","name":"Plane stamp"}]})");check(session.call("doc_apply",bad).find("isError")->b&&session.revision==revision&&ark::documentToJson(session.document)==before,"Stale stamp mutation preserves revision and source");bad.set("expected_revision",V::makeNum(revision));bad.set("commands",json(R"([{"op":"image_asset.remove","name":"Logo"}])"));check(session.call("doc_apply",bad).find("isError")->b&&session.revision==revision&&ark::documentToJson(session.document)==before,"Deleting referenced image rejects atomically");bad.set("commands",json(R"([{"op":"stamp.set","name":"Broken","asset":"Logo","u_axis":[1,0,0],"v_axis":[1,0,0],"width":10,"height":10}])"));check(session.call("doc_apply",bad).find("isError")->b&&session.revision==revision&&ark::documentToJson(session.document)==before,"Invalid projector axes leave source/revision unchanged");
    auto downgraded=root;downgraded.set("version",V::makeNum(38));check(!ark::documentFromJson(downgraded.dump(),restored,&error)&&ark::documentToJson(restored,true,false)==saved,"New source cannot hide in an old document format");
    ark::Document legacy;check(ark::documentFromJson(R"({"format":"ark","version":1,"units":"mm","features":[]})",legacy,&error)&&json(ark::documentToJson(legacy)).find("version")->num==1,"Old empty document remains format1");check(ark::documentFromJson(R"({"format":"ark","version":13,"units":"mm","features":[],"canvases":[{"name":"Legacy","path":"unavailable.png","plane":"XY","width":"20","height":"15","opacity":0.5}]})",legacy,&error)&&json(ark::documentToJson(legacy)).find("version")->num==13,"Legacy missing-path canvas remains readable without image embedding");
    auto corrupted=root;auto rows=*corrupted.find("image_assets");rows.arr.front().set("sha256",V::makeStr(std::string(64,'0')));corrupted.set("image_assets",rows);check(!ark::documentFromJson(corrupted.dump(),restored,&error)&&ark::documentToJson(restored,true,false)==saved,"Corrupted embedded source load leaves prior document intact");
}
void projection(){ark::Mesh mesh;for(const auto& point:{ark::Vec3{-5,-5,0},ark::Vec3{5,-5,0},ark::Vec3{5,5,0},ark::Vec3{-5,5,0}})mesh.addVertex(point);mesh.addTri(0,1,2);mesh.addTri(0,2,3);ark::StampProjector frame;frame.width=4;frame.height=2;frame.depth=.1;const auto projected=ark::projectStampTriangles(mesh,0,2,frame);check(!projected.empty()&&projected.size()%3==0,"Projector clips partial triangles into renderable UV triangles");double area=0;for(size_t i=0;i<projected.size();i+=3)area+=(projected[i+1].position-projected[i].position).cross(projected[i+2].position-projected[i].position).len()/2;check(std::abs(area-8)<1e-8,"UV rectangle clips exact planar fixture area");for(const auto& point:projected)check(point.uv.x>=-1e-12&&point.uv.x<=1+1e-12&&point.uv.y>=-1e-12&&point.uv.y<=1+1e-12,"All clipped UVs remain within image rectangle");mesh.flip();check(ark::projectStampTriangles(mesh,0,2,frame).empty(),"Front-only projector rejects backside triangles");frame.frontOnly=false;check(!ark::projectStampTriangles(mesh,0,2,frame).empty(),"Explicit double-sided projection remains available");frame.origin.z=1;check(ark::projectStampTriangles(mesh,0,2,frame).empty(),"Depth slab excludes remote parallel surface");rejects([&]{ark::projectStampTriangles(mesh,1,2,frame);},"Invalid triangle span rejects");
    auto bad=json(R"({"name":"Bad","asset":"Logo","feature":1,"width":4,"height":2})");rejects([&]{ark::stampFromJson(bad);},"Body projector needs exact faces and topology");
}
void containers(){ark::AgentSession parent;accepted(parent.call("doc_apply",json(R"({"expected_revision":0,"commands":[{"op":"feature.add","name":"Scoped box","type":"box","p":{"dx":10,"dy":10,"dz":10}},{"op":"assembly.add","name":"Group","feature":0},{"op":"assembly.add","name":"Part","parent":1,"feature":1}]})")));V request=json(R"({"node":1})");request.set("expected_revision",V::makeNum(parent.revision));const auto checkout=ark::checkoutDesignContainer(parent.document,parent.revision,request);ark::Document child;std::string error;check(ark::documentFromJson(checkout.find("document")->dump(),child,&error),"Ordinary geometry container checkout remains available");
    auto introduced=child.authoringCopy();introduced.imageAssets.push_back(ark::imageAssetFromJson(fixture()));bool explicitBoundary=false;try{ark::validateDesignContainerTransition(child,introduced);}catch(const std::exception& e){explicitBoundary=std::string(e.what()).find("CONTAINER_UNSUPPORTED_APPEARANCE")!=std::string::npos;}check(explicitBoundary,"Child transition explicitly rejects unowned embedded appearance assets");
    auto withImage=parent.document.authoringCopy();withImage.imageAssets.push_back(ark::imageAssetFromJson(fixture()));explicitBoundary=false;try{ark::checkoutDesignContainer(withImage,parent.revision,request);}catch(const std::exception& e){explicitBoundary=std::string(e.what()).find("CONTAINER_UNSUPPORTED_APPEARANCE")!=std::string::npos;}check(explicitBoundary,"Checkout cannot silently drop even an unused embedded asset");
    V merge=request;merge.set("document",json(ark::documentToJson(introduced,false,false)));explicitBoundary=false;try{ark::proposeDesignContainerMerge(parent.document,parent.revision,merge);}catch(const std::exception& e){explicitBoundary=std::string(e.what()).find("CONTAINER_UNSUPPORTED_APPEARANCE")!=std::string::npos;}check(explicitBoundary,"Merge explicitly rejects child asset ownership instead of ignoring it");
    // This checks authoring/version transport. Native split geometry has its
    // independent OCCT corpus; this bounded source is not evaluated here.
    auto split=parent.document.authoringCopy();ark::Sketch mark;mark.addCircle(5,5,2);split.setSketch("Mark",mark);ark::Feature feature;feature.type=ark::FeatureType::NativeSolid;feature.name="Regions";feature.inputs={1};feature.nativeSpec=json(R"({"op":"split_line","sketch":"Mark","source_face":"z_max","direction":[0,0,-1]})");feature.nativeSpec.set("source_topology",V::makeStr(std::string(64,'1')));const auto newId=split.addFeature(feature);split.assembly.back().feature=newId;const auto splitCheckout=ark::checkoutDesignContainer(split,parent.revision,request);check(splitCheckout.find("document")->find("version")->num==39,"Bare split-line source39 checkout retains its required version");
}
#ifdef ARK_APPEARANCE_NATIVE_TESTS
void geometry(){ark::AgentSession session;apply(session,json(R"({"op":"feature.add","name":"Box","type":"native_solid","native":{"op":"box"},"p":{"width":10,"depth":20,"height":30}})"));apply(session,importCommand());const auto& topology=*session.document.evalBodies.front().nativeData.find("topology");const auto digest=topology.find("brep_sha256")->str;V patch=json(R"({"op":"face_appearance.set","id":"Box","face":"z_max","appearance":{"base_color":[0.1,0.8,0.2],"texture_asset":"Logo"}})");patch.set("source_topology",V::makeStr(digest));const auto paint=apply(session,patch);check(!paint.find("geometry_recomputed")->b,"Face appearance does not rebuild exact geometry");const auto appearance=ark::resolvedFaceAppearance(session.document,session.document.features.front(),"z_max");check(appearance.baseColor.y==.8&&appearance.textureAsset=="Logo","Exact selected face resolves its own region material");
    V stamp=json(R"({"op":"stamp.set","name":"Body logo","asset":"Logo","feature":"Box","faces":["z_max"],"origin":[5,10,30],"width":6,"height":4,"depth":0.1})");stamp.set("source_topology",V::makeStr(digest));apply(session,stamp);const auto saved=ark::documentToJson(session.document);const auto revision=session.revision;V edit=json(R"({"commands":[{"op":"feature.edit","id":"Box","p":{"width":12}}]})");edit.set("expected_revision",V::makeNum(revision));check(session.call("doc_apply",edit).find("isError")->b&&session.revision==revision&&ark::documentToJson(session.document)==saved,"Geometry change cannot silently rebind face material or stamp");
    patch.set("source_topology",V::makeStr(std::string(64,'0')));V commands=V::makeArr();commands.arr.push_back(patch);edit.set("commands",commands);check(session.call("doc_apply",edit).find("isError")->b&&session.revision==revision&&ark::documentToJson(session.document)==saved,"Stale face appearance topology rejects atomically");patch.set("source_topology",V::makeStr(digest));patch.set("appearance",json(R"({"opacity":0.5})"));commands.arr[0]=patch;edit.set("commands",commands);check(session.call("doc_apply",edit).find("isError")->b&&session.revision==revision,"Independent transparent face opacity rejects");
    ark::Document restored;std::string error;check(ark::documentFromJson(saved,restored,&error),("Exact face/stamp source loads: "+error).c_str());restored.recompute();ark::validateAppearanceAuthoring024B(restored,true);check(ark::resolvedFaceAppearance(restored,restored.features.front(),"z_max").baseColor.y==.8,"Exact region appearance persists after source recomputation");
    const auto authoring=ark::documentToJson(restored,false,false);ark::Document undo;ark::iterationRestore(restored,ark::iterationUndoTarget(restored,false),undo);check(undo.stamps.empty()&&undo.imageAssets.size()==1&&undo.features.front().faceAppearances.size()==1,"Format39 history restore preserves the observed image and face authoring before the Stamp step");
    auto future=json(saved);future.set("version",V::makeNum(40));check(!ark::documentFromJson(future.dump(),restored,&error)&&ark::documentToJson(restored,false,false)==authoring,"Unsupported future format40 history rejects without replacing existing format39 authoring");
}
#endif
}
